    { op: 'add', path: '/a/0', value: { n: 1 } },
    { op: 'remove', path: '/b/c' },
    { op: 'move', from: '/a/1', path: '/z' },
    { op: 'copy', from: '/a', path: '/y' },
    { op: 'replace', path: '/a/0/n', value: 2 },
    { op: 'test', path: '/nope', value: 1 },
  ];
