    { op: 'add', path: '/list', value: [] },
    { op: 'add', path: '/list/-', value: 'a' },
    { op: 'add', path: '/list/0', value: 'b' },
    { op: 'test', path: '/list', value: ['b', 'a'] },
  ]);
  assert.deepEqual(out, { list: ['b', 'a'] });
});

test('deep values do not overflow', () => {
  let doc = 0;
  for (let i = 0; i < 1000; i++) doc = [doc];
