14	export function parsePointer(pointer) {
15	  if (typeof pointer !== 'string') throw new TypeError('pointer must be a string');
16	  const tokens = tryParsePointer(pointer);
17	  if (tokens === null) throw new SyntaxError('invalid pointer');
18	  return tokens;
19	}
20	
21	// Returns the decoded tokens, or null when the pointer is invalid.
22	function tryParsePointer(pointer) {
23	  if (pointer === '') return [];
24	  if (pointer[0] !== '/') return null;
25	  if (/~([^01]|$)/.test(pointer)) return null;
26	  return pointer
27	    .slice(1)
28	    .split('/')
29	    .map((token) => token.replace(/~1/g, '/').replace(/~0/g, '~'));
30	}
31	
32	function isObject(value) {
33	  return value !== null && typeof value === 'object' && !Array.isArray(value);
34	}
35	
36	function isContainer(value) {
37	  return value !== null && typeof value === 'object';
38	}
39	
40	// Sets an own data property without triggering setters such as __proto__.
41	function setMember(obj, key, value) {
42	  Object.defineProperty(obj, key, { value, writable: true, enumerable: true, configurable: true });
43	}
44	
45	// Deep copy of a JSON value, iterative so deep values do not overflow the stack.
46	function clone(value) {
47	  if (!isContainer(value)) return value;
48	  const emptyLike = (v) => (Array.isArray(v) ? [] : {});
49	  const root = emptyLike(value);
50	  const stack = [[value, root]];
51	  while (stack.length > 0) {
52	    const [src, dst] = stack.pop();
53	    const copyChild = (child) => {
54	      if (!isContainer(child)) return child;
55	      const copy = emptyLike(child);
56	      stack.push([child, copy]);
57	      return copy;
58	    };
59	    if (Array.isArray(src)) {
60	      for (let i = 0; i < src.length; i++) dst.push(copyChild(src[i]));
61	    } else {
62	      for (const key of Object.keys(src)) setMember(dst, key, copyChild(src[key]));
63	    }
64	  }
65	  return root;
66	}
67	
68	function jsonType(value) {
69	  if (value === null) return 'null';
70	  if (Array.isArray(value)) return 'array';
71	  return typeof value;
72	}
73	
74	function deepEqual(a, b) {
75	  const stack = [[a, b]];
76	  while (stack.length > 0) {
77	    const [x, y] = stack.pop();
78	    const type = jsonType(x);
79	    if (type !== jsonType(y)) return false;
80	    if (type === 'array') {
81	      if (x.length !== y.length) return false;
82	      for (let i = 0; i < x.length; i++) stack.push([x[i], y[i]]);
83	    } else if (type === 'object') {
84	      const keys = Object.keys(x);
85	      if (keys.length !== Object.keys(y).length) return false;
86	      for (const key of keys) {
87	        if (!Object.hasOwn(y, key)) return false;
88	        stack.push([x[key], y[key]]);
