12	class CliError extends Error {
13	  constructor(message, exitCode) {
14	    super(message);
15	    this.exitCode = exitCode;
16	  }
17	}
18	
19	function fileError(code) {
20	  if (code === 'ENOENT' || code === 'ENOTDIR') return 'no such file';
21	  if (code === 'EISDIR') return 'is a directory';
22	  return 'cannot read';
23	}
