33	function readFileBytes(path) {
34	  let fd;
35	  try {
36	    fd = fs.openSync(path, 'r');
37	  } catch (err) {
38	    const reason = fileError(err.code);
39	    return reason === 'cannot read' && isDirectory(path) ? 'is a directory' : reason;
40	  }
41	  try {
42	    if (fs.fstatSync(fd).isDirectory()) return 'is a directory';
43	    const chunks = [];
44	    let total = 0;
